  <path d="M4 70 A116 12 0 1 1 236 70 A116 12 0 1 1 4 70 Z M89 70 A31 3.8 0 1 0 151 70 A31 3.8 0 1 0 89 70 Z" fill="url(#space-black-hole-disk)" fill-rule="evenodd"/>
